mapper.select:
SELECT hra.marketing_attachment_id, hra.document_name, hra.marketing_report_id, hra.description, hra.attachment_category, hra.upload_date, (select wm_concat(fa.attachment_id) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name in ('hls_report_attachment','HLS_MARKETING_REPORT_DOCX') and hra.marketing_attachment_id = fam.table_pk_value) attachment_id, (select wm_concat(fa.file_name) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name in ('hls_report_attachment','HLS_MARKETING_REPORT_DOCX') and hra.marketing_attachment_id = fam.table_pk_value) file_name, (SELECT su.description FROM sys_user su WHERE hra.UPLOAD_PERSON = su.user_id) UPLOAD_PERSON_n, hra.status FROM HLS_REPORT_ATTACHMENT hra
hra.attachment_category in ('MARKETING_REPORT_ATT','HLS_MARKETING_REPORT_DOCX')
and hra.marketing_report_id = #{marketingReportId}
